                                                                      "title":  "가위바위보 웹사이트",
                                                                      "description":  "브라우저에서 바로 실행할 수 있는 단일 HTML 결과물",
                                                                      "src":  "./guidebook-assets/claude_code_rock_paper_scissors.html",
                                                                      "fileName":  "claude-code-rock-paper-scissors.html"
