                         "role":  "목소리·내레이션부터 효과음·음악·이미지·영상·전사·더빙까지 한곳에서 만들고 편집하는 AI 콘텐츠 제작 서비스",
                         "basis":  "2026-08-26",
                         "guideDate":  "2026-08-26",
                         "overview":  "음성 합성과 변환을 중심으로 효과음·음악·이미지·영상 제작, 음성 전사, 더빙과 Studio 통합 편집까지 제공하는 ElevenLabs의 콘텐츠 제작 플랫폼입니다.",
